.techpivot-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2e22;
    background: linear-gradient(160deg, #f1f6ec 0%, #e7f0e0 100%);
    border-radius: 18px;
}

.techpivot-container * {
    box-sizing: border-box;
}

.techpivot-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f4d2e 0%, #2f7d46 55%, #4ca364 100%);
    color: #f3fbf0;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 77, 46, 0.30);
}

.techpivot-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.techpivot-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #cdeccb;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.techpivot-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3f3df;
}

.techpivot-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #245a36;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.techpivot-period-counter #currentDay,
.techpivot-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f4d2e;
}

.techpivot-round-name {
    background: #d3e9cf;
    color: #1f4d2e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.techpivot-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c4a16;
    background: #fbead9;
    padding: 4px 12px;
    border-radius: 999px;
}

.techpivot-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.techpivot-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d8e6d0;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.06);
    border-top: 4px solid #2f7d46;
}

.techpivot-card-home { border-top-color: #2f7d46; }
.techpivot-card-eu { border-top-color: #2f6fb0; }
.techpivot-card-roi { border-top-color: #c98a16; }
.techpivot-card-cash { border-top-color: #7a5230; }

.techpivot-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5c7060;
}

.techpivot-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f4d2e;
}

.techpivot-card-home .techpivot-value { color: #2f7d46; }
.techpivot-card-eu .techpivot-value { color: #2f6fb0; }
.techpivot-card-roi .techpivot-value { color: #c98a16; }
.techpivot-card-cash .techpivot-value { color: #7a5230; }

.techpivot-sublabel {
    font-size: 0.76rem;
    color: #6c8170;
    line-height: 1.35;
}

.techpivot-cash-danger .techpivot-value { color: #c0392b; }
.techpivot-cash-danger { border-top-color: #c0392b; }
.techpivot-cash-safe .techpivot-value { color: #2f7d46; }

.techpivot-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f4d2e;
    color: #eaf6e6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.techpivot-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.techpivot-budget-over #budgetDisplay {
    color: #ffb3a3;
}

.techpivot-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7d46;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.05);
}

.techpivot-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.techpivot-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f4d2e;
    margin-bottom: 6px;
}

.techpivot-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c4434;
}

.techpivot-briefing-text strong { color: #2f7d46; }
.techpivot-briefing-text em { color: #9c4a16; font-style: italic; }

.techpivot-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d8e6d0;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.06);
}

.techpivot-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f4d2e;
    border-bottom: 2px solid #e4efdd;
    padding-bottom: 8px;
}

.techpivot-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #244033;
    margin: 14px 0 6px;
}

.techpivot-container select,
.techpivot-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6b4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fbf4;
    color: #1d2e22;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.techpivot-container select:focus,
.techpivot-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d46;
    box-shadow: 0 0 0 3px rgba(47, 125, 70, 0.15);
}

.techpivot-container select option {
    background-color: #ffffff;
    color: #1d2e22;
}

.techpivot-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d46;
}

.techpivot-range-readout,
.techpivot-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f6fb0;
    margin-top: 4px;
}

.techpivot-range-readout span:last-child,
.techpivot-alloc-readout span:nth-child(2) {
    color: #2f7d46;
    font-weight: 800;
}

.techpivot-hint {
    font-size: 0.8rem;
    color: #6c8170;
    margin-top: 4px;
    line-height: 1.4;
}

.techpivot-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.techpivot-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9ef;
    border: 1px solid #dcebd4;
    border-radius: 9px;
    padding: 8px 12px;
}

.techpivot-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #244033;
}

.techpivot-alloc-row input[type="number"] {
    width: 110px;
    flex: 0 0 110px;
}

.techpivot-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.techpivot-container .btn-primary {
    background: linear-gradient(135deg, #1f4d2e 0%, #2f7d46 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 77, 46, 0.28);
}

.techpivot-container .btn-primary:hover {
    filter: brightness(1.08);
}

.techpivot-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6b4;
    color: #5c7060;
}

.techpivot-coach {
    background: #1f4d2e;
    color: #eaf6e6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 77, 46, 0.22);
}

.techpivot-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9ed7a4;
    margin-bottom: 8px;
}

.techpivot-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.techpivot-coach-body strong { color: #ffe08a; }
.techpivot-coach-body em { color: #ffc1a3; font-style: italic; }

.techpivot-history,
.techpivot-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d8e6d0;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.06);
}

.techpivot-history h3,
.techpivot-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f4d2e;
}

.techpivot-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #244033;
}

.techpivot-container table#usfHistoryTable th {
    background: #e9f3e3;
    color: #1f4d2e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6cc;
}

.techpivot-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4ea;
}

.techpivot-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf6;
}

.techpivot-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .techpivot-container {
        padding: 14px;
    }
    .techpivot-header h1 {
        font-size: 1.7rem;
    }
    .techpivot-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .techpivot-value {
        font-size: 2rem;
    }
    .techpivot-clock {
        margin-left: 0;
    }
    .techpivot-period-counter {
        font-size: 0.88rem;
    }
    .techpivot-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .techpivot-alloc-row {
        flex-wrap: wrap;
    }
    .techpivot-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .techpivot-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion debrief — self-contained, append-only. Tech Pivot (agro) palette. */
.tpsim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e2b22; text-align: center; padding: 4px 2px 8px; }
.tpsim-cm-title { font-size: 20px; font-weight: 700; color: #1f4d2e; margin-bottom: 14px; }
.tpsim-cm-scorewrap { background: linear-gradient(135deg, #1f4d2e 0%, #2f7d46 55%, #4ca364 100%); color: #ffffff; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.tpsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.tpsim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.tpsim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.tpsim-cm-badges { margin-top: 10px; }
.tpsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.tpsim-cm-badge-ok { background: #d8e6d0; color: #1f4d2e; }
.tpsim-cm-badge-miss { background: #f6dcd2; color: #9a2f17; }
.tpsim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 520px; }
.tpsim-cm-kpi { flex: 1 1 108px; min-width: 108px; background: #f1f6ec; border: 1px solid #d8e6d0; border-radius: 10px; padding: 10px 6px; }
.tpsim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #1f4d2e; }
.tpsim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #55605a; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.tpsim-cm-insights { text-align: left; max-width: 540px; margin: 0 auto; background: #f6faf3; border-left: 4px solid #2f7d46; border-radius: 8px; padding: 12px 16px; }
.tpsim-cm-ins-h { font-weight: 700; color: #1f4d2e; margin-bottom: 6px; font-size: 14px; }
.tpsim-cm-insights ul { margin: 0; padding-left: 18px; }
.tpsim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #263528; }
@media (max-width: 480px) { .tpsim-cm-kpi { flex-basis: 40%; } .tpsim-cm-score { font-size: 38px; } .tpsim-cm-scorewrap { max-width: 100%; } }

