(function() {
    'use strict';

    class TechPivotAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Tech Pivot`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // NUMBERS REFERENCE CARD (COP$ millones).
            this.BUDGET_CAP = 4200;        // fixed annual R&D budget
            this.CASH_START = 2400;        // cash on hand
            this.UNDRAWN_CREDIT = 1500;    // undrawn Bancolombia facility
            this.SUBSIDIARY_COST = 5000;   // wholly-owned subsidiary ~COP$5.000M, exceeds cash

            // Project ship costs (COP$ millones) — funding below the "needs" figure ships late.
            this.PROJ_NEED = { nextgen: 2000, cecert: 1800, aimodule: 1800, lite: 2000 };

            // KPI start values (mirror the HTML seeds; kept low for headroom so single
            // classic errors still move the final tier rather than saturating against the cap).
            this.START = { home: 16, eu: 3, roi: 10, cash: 6.0 };

            // Final-screen gates.
            this.HOME_TARGET = 62;
            this.EU_TARGET = 55;
            this.ROI_TARGET = 60;
            this.CASH_SAFE = 6.0;     // payroll risk under 6 months
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    home: this.START.home,
                    eu: this.START.eu,
                    roi: this.START.roi,
                    cash: this.START.cash,
                    budgetUsed: 0,
                    overBudget: false,
                    homeHistory: [this.START.home],
                    euHistory: [this.START.eu],
                    roiHistory: [this.START.roi],
                    cashHistory: [this.START.cash],
                    insolvent: false,
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diagnosis: `defendonly`,
                    threat: `slow`,
                    honesty: 50,
                    nextgen: 1000,
                    cecert: 1000,
                    aimodule: 1100,
                    lite: 1100,
                    pause: `none`,
                    mode: `jv`,
                    timing: `now`,
                    gate: 50,
                    sequence: `clockfirst`,
                    contingency: `cuthome`,
                    reserve: 40,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const diag = document.getElementById(`diagnosisInput`);
                const threat = document.getElementById(`threatInput`);
                const hon = document.getElementById(`honestyInput`);
                if (diag) decisions.diagnosis = diag.value;
                if (threat) decisions.threat = threat.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const ng = document.getElementById(`nextgenInput`);
                const ce = document.getElementById(`cecertInput`);
                const ai = document.getElementById(`aimoduleInput`);
                const lt = document.getElementById(`liteInput`);
                const pause = document.getElementById(`pauseInput`);
                if (ng) decisions.nextgen = parseFloat(ng.value);
                if (ce) decisions.cecert = parseFloat(ce.value);
                if (ai) decisions.aimodule = parseFloat(ai.value);
                if (lt) decisions.lite = parseFloat(lt.value);
                if (pause) decisions.pause = pause.value;
                const parts = [decisions.nextgen, decisions.cecert, decisions.aimodule, decisions.lite];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = decisions.nextgen + decisions.cecert + decisions.aimodule + decisions.lite;
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_over`); return false;
                }
            } else if (round === 3) {
                const mode = document.getElementById(`modeInput`);
                const timing = document.getElementById(`timingInput`);
                const gate = document.getElementById(`gateInput`);
                if (mode) decisions.mode = mode.value;
                if (timing) decisions.timing = timing.value;
                if (gate) decisions.gate = parseInt(gate.value, 10);
                if (!Number.isFinite(decisions.gate) || decisions.gate < 0 || decisions.gate > 100) {
                    warn(`warn_gate_range`); return false;
                }
            } else if (round === 4) {
                const seq = document.getElementById(`sequenceInput`);
                const cont = document.getElementById(`contingencyInput`);
                const res = document.getElementById(`reserveInput`);
                const cv = document.getElementById(`convictionInput`);
                if (seq) decisions.sequence = seq.value;
                if (cont) decisions.contingency = cont.value;
                if (res) decisions.reserve = parseInt(res.value, 10);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.reserve) || decisions.reserve < 0 || decisions.reserve > 100) {
                    warn(`warn_reserve_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let homeDelta = 0, euDelta = 0, roiDelta = 0, cashDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the position: concentrate is the textbook-correct frame.
                switch (d.diagnosis) {
                    case `concentrate`: homeDelta += 8; euDelta += 4; roiDelta += 14; coachKey = `coach_r1_concentrate`; break;
                    case `keepoptions`: homeDelta += 2; euDelta += 1; roiDelta -= 10; coachKey = `coach_r1_keepoptions`; break;
                    case `euonly`: homeDelta -= 10; euDelta += 8; roiDelta -= 4; coachKey = `coach_r1_euonly`; break;
                    case `defendonly`: homeDelta += 6; euDelta -= 8; roiDelta -= 2; coachKey = `coach_r1_defendonly`; break;
                }

                // Threat realism: the cheaper rival lands in ~5 months and erodes the recurring base.
                switch (d.threat) {
                    case `real`: homeDelta += 10; roiDelta += 6; if (d.diagnosis === `concentrate`) coachKey = `coach_r1_sharp`; break;
                    case `slow`: homeDelta -= 6; roiDelta -= 2; coachKey = `coach_r1_slow`; break;
                    case `none`: homeDelta -= 12; roiDelta -= 6; coachKey = `coach_r1_none`; break;
                }

                // Honesty: accepting that all three fronts at once is infeasible.
                if (d.honesty >= 60) { roiDelta += 6; }
                else if (d.honesty <= 25) { roiDelta -= 6; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.diagnosis === `concentrate` && d.threat === `real`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Prioritise the portfolio under the fixed COP$4.200M budget.
                const ng = d.nextgen, ce = d.cecert, ai = d.aimodule, lt = d.lite;
                ds.budgetUsed = Math.round(ng + ce + lt + ai);

                // A project funded at/above its "needs" figure ships on time and delivers; below it
                // ships late and delivers a fraction. Concentration beats peanut-buttering.
                const ship = (spend, need) => {
                    if (spend <= 0) return 0;
                    if (spend >= need) return 1;            // ships on the clock
                    const r = spend / need;
                    return r >= 0.85 ? r * 0.7 : r * 0.35;  // underfunded = sharply late, little value
                };
                const sNg = ship(ng, this.PROJ_NEED.nextgen);   // defends home vs the Brazilian rival
                const sCe = ship(ce, this.PROJ_NEED.cecert);    // opens the EU deal
                const sAi = ship(ai, this.PROJ_NEED.aimodule);  // lifts ARPU on the recurring base
                const sLt = ship(lt, this.PROJ_NEED.lite);      // defends the value segment

                homeDelta += Math.round(sNg * 24 + sLt * 12);
                euDelta += Math.round(sCe * 30);
                roiDelta += Math.round(sAi * 16);

                // Peanut-buttering penalty: four projects all started but none fully shipped.
                const started = [ng, ce, ai, lt].filter((v) => v > 0).length;
                const shipped = [sNg, sCe, sAi, sLt].filter((v) => v >= 1).length;
                if (started >= 4 && shipped === 0) {
                    homeDelta -= 14; euDelta -= 12; roiDelta -= 16; coachKey = `coach_r2_peanut`;
                } else if (shipped >= 2) {
                    roiDelta += 12; coachKey = `coach_r2_concentrated`;
                } else if (shipped === 1) {
                    roiDelta += 4; coachKey = `coach_r2_thin`;
                } else {
                    coachKey = `coach_r2_thin`;
                }

                // Starving the recurring base (no AI module) hurts ROI.
                if (ai <= 0) { roiDelta -= 6; }

                // Pausing legacy projects frees cash and R&D focus; pausing the recurring platform
                // is a false economy that bleeds the cash engine.
                switch (d.pause) {
                    case `lowvalue`: cashDelta += 1.0; roiDelta += 6; if (shipped >= 2) coachKey = `coach_r2_focus`; break;
                    case `none`: cashDelta -= 0.6; roiDelta -= 4; break;
                    case `recurring`: cashDelta += 0.4; homeDelta -= 10; roiDelta -= 8; coachKey = `coach_r2_recurring`; break;
                }

                // Spending the full budget consumes cash this round.
                cashDelta -= (ds.budgetUsed / this.BUDGET_CAP) * 1.4;

                summaryKey = (shipped >= 2 && d.pause === `lowvalue`) ? `sum_r2_good` : (started >= 4 && shipped === 0 ? `sum_r2_peanut` : `sum_r2_weak`);
            } else if (round === 3) {
                // Internationalisation entry mode — control vs commitment vs cash vs speed.
                switch (d.mode) {
                    case `distributor`: euDelta += 18; cashDelta += 0.8; roiDelta += 8; coachKey = `coach_r3_distributor`; break;
                    case `jv`: euDelta += 14; cashDelta -= 0.6; roiDelta += 4; coachKey = `coach_r3_jv`; break;
                    case `subsidiary`: euDelta += 10; cashDelta -= 3.0; roiDelta -= 10; coachKey = `coach_r3_subsidiary`; break;
                    case `skip`: euDelta -= 14; homeDelta += 6; cashDelta += 0.6; coachKey = `coach_r3_skip`; break;
                }
                // The subsidiary needs ~COP$5.000M the firm does not have — over-commitment risk.
                if (d.mode === `subsidiary`) { ds.overBudget = true; }

                // Timing: phased real-options entry beats an all-in launch for a cash-fragile SME.
                switch (d.timing) {
                    case `phased`: euDelta += 10; homeDelta += 6; cashDelta += 0.6; if (d.mode === `distributor`) coachKey = `coach_r3_disciplined`; break;
                    case `now`: euDelta += 4; homeDelta -= 8; cashDelta -= 1.0; coachKey = (coachKey === `coach_default`) ? `coach_r3_now` : coachKey; break;
                    case `defer`: euDelta -= 8; homeDelta += 4; coachKey = `coach_r3_defer`; break;
                }

                // Go/no-go gate: tying EU spend to CE + first order protects cash.
                if (d.gate >= 60) { cashDelta += 0.8; roiDelta += 6; }
                else if (d.gate <= 25) { cashDelta -= 0.6; roiDelta -= 4; coachKey = `coach_r3_nogate`; }

                summaryKey = ((d.mode === `distributor` || d.mode === `jv`) && d.timing === `phased`) ? `sum_r3_good` : (d.mode === `subsidiary` ? `sum_r3_overcommit` : `sum_r3_weak`);
            } else if (round === 4) {
                // Sequence against the clocks + cash-runway check + contingency.
                switch (d.sequence) {
                    case `balanced`: homeDelta += 10; euDelta += 8; roiDelta += 12; coachKey = `coach_r4_balanced`; break;
                    case `clockfirst`: homeDelta += 8; euDelta -= 2; roiDelta += 4; coachKey = `coach_r4_clockfirst`; break;
                    case `quality`: homeDelta -= 12; euDelta -= 4; roiDelta -= 8; coachKey = `coach_r4_quality`; break;
                }

                // Contingency: cut EU first to protect the home cash engine that funds R&D.
                switch (d.contingency) {
                    case `cuteu`: homeDelta += 8; cashDelta += 0.6; roiDelta += 6; break;
                    case `cuthome`: homeDelta -= 12; euDelta += 2; roiDelta -= 6; coachKey = `coach_r4_cuthome`; break;
                    case `none`: cashDelta -= 1.4; roiDelta -= 8; coachKey = `coach_r4_nocont`; break;
                }

                // Cash reserve against front-loaded spend and the revenue lag.
                if (d.reserve >= 35 && d.reserve <= 60) { cashDelta += 2.2; roiDelta += 4; }
                else if (d.reserve < 20) { cashDelta -= 2.2; coachKey = `coach_r4_noreserve`; }
                else if (d.reserve > 75) { cashDelta += 1.0; roiDelta -= 6; coachKey = `coach_r4_hoard`; }
                else { cashDelta += 1.0; }

                // Pitch conviction defends the runway, not just the strategy.
                roiDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.sequence === `balanced` && d.contingency === `cuteu` && d.reserve >= 35 && d.reserve <= 60) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with bounds (KPIs 0–100, cash a months figure).
            ds.home = Math.max(0, Math.min(100, ds.home + homeDelta));
            ds.eu = Math.max(0, Math.min(100, ds.eu + euDelta));
            ds.roi = Math.max(0, Math.min(100, ds.roi + roiDelta));
            ds.cash = Math.max(0, Math.round((ds.cash + cashDelta) * 10) / 10);

            if (ds.cash < this.CASH_SAFE) ds.insolvent = (ds.cash < 4.0);

            ds.homeHistory.push(Math.round(ds.home));
            ds.euHistory.push(Math.round(ds.eu));
            ds.roiHistory.push(Math.round(ds.roi));
            ds.cashHistory.push(Math.round(ds.cash * 10) / 10);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where the gradebook/score resolver reads it
            // (domainState.performance.overallScore first, then a top-level score/netWorth).
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = { overallScore: _score };

            return {
                period: state.currentPeriod,
                home: Math.round(ds.home),
                homeDelta: Math.round(homeDelta),
                eu: Math.round(ds.eu),
                euDelta: Math.round(euDelta),
                roi: Math.round(ds.roi),
                roiDelta: Math.round(roiDelta),
                cash: Math.round(ds.cash * 10) / 10,
                cashDelta: Math.round(cashDelta * 10) / 10,
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

