            // Reserve slider readout (R4).
            this._wireRange(`reserveInput`, `reserveReadout`);

            // Live R&D allocation total (R2).
            const allocIds = [`nextgenInput`, `cecertInput`, `aimoduleInput`, `liteInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = self._fmtMillones(total);
                const bar = document.querySelector(`.techpivot-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _wireRange(inputId, readoutId) {
            const input = document.getElementById(inputId);
            const readout = document.getElementById(readoutId);
            if (input && readout) {
                readout.textContent = input.value;
                input.addEventListener(`input`, function() { readout.textContent = input.value; });
            }
