        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const home = Math.round(ds.home);
            const eu = Math.round(ds.eu);
            const roi = Math.round(ds.roi);
            const cash = Math.round(ds.cash * 10) / 10;
            const solvent = cash >= this.CASH_SAFE;
            const cashScore = Math.min(100, (cash / 12) * 100);
            let composite = Math.round(home * 0.30 + eu * 0.22 + roi * 0.28 + cashScore * 0.20);
            if (!solvent) composite = Math.round(composite * 0.7);
            return composite;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const home = Math.round(ds.home);
            const eu = Math.round(ds.eu);
            const roi = Math.round(ds.roi);
            const cash = Math.round(ds.cash * 10) / 10;

            const solvent = cash >= this.CASH_SAFE;
            const homeOk = home >= this.HOME_TARGET;
            const euOk = eu >= this.EU_TARGET;
            const roiOk = roi >= this.ROI_TARGET;

            // Composite: a brilliant plan with no runway is a bankruptcy plan — cash gates the top tier.
            // cashScore tops out at 12 months so a healthy-but-not-hoarded runway does not pin the
            // dimension at 100, keeping cash a live discriminator rather than a saturated freebie.
            let composite = this._composite(ds);

            let performance = window.mySimulation.t(`perf_subscale`);
            if (homeOk && euOk && roiOk && solvent && composite >= 78) performance = window.mySimulation.t(`perf_concentrated`);
            else if (homeOk && roiOk && solvent && composite >= 58) performance = window.mySimulation.t(`perf_disciplined`);
            else if (!solvent) performance = window.mySimulation.t(`perf_bankruptcy`);
            else if (euOk && !homeOk) performance = window.mySimulation.t(`perf_floorlost`);
            else if (composite >= 50) performance = window.mySimulation.t(`perf_partial`);

            const met = homeOk && roiOk && solvent && composite >= 58;
            const insights = [];
            if (homeOk && euOk && roiOk && solvent) insights.push(window.mySimulation.t(`insight_concentrated`));
            else if (!solvent) insights.push(window.mySimulation.t(`insight_runway`));
            else if (euOk && !homeOk) insights.push(window.mySimulation.t(`insight_floorlost`));
            else if (!homeOk) insights.push(window.mySimulation.t(`insight_homeweak`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (!roiOk) insights.push(window.mySimulation.t(`insight_peanut`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overcommit`));
            if (!euOk && eu < 30) insights.push(window.mySimulation.t(`insight_noeu`));
            if (homeOk && euOk && roiOk && solvent && composite >= 80) insights.push(window.mySimulation.t(`insight_exemplary`));

            return {
                home: home,
                eu: eu,
                roi: roi,
                cash: cash,
                solvent: solvent,
                composite: composite,
                performance: performance,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performance || ``;
            const badge = s.met
                ? `<span class="tpsim-cm-badge tpsim-cm-badge-ok">${t(`cm_targets_met`)}</span>`
                : `<span class="tpsim-cm-badge tpsim-cm-badge-miss">${t(`cm_targets_missed`)}</span>`;
            const kpi = (k, v, suf) => `<div class="tpsim-cm-kpi"><div class="tpsim-cm-kpi-val">${(v != null ? v : `—`)}${suf || ``}</div><div class="tpsim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="tpsim-cm-insights"><div class="tpsim-cm-ins-h">${t(`cm_insights`)}</div><ul>${ins.map((i) => `<li>${i}</li>`).join(``)}</ul></div>`
                : ``;
            return `
                <div class="tpsim-cm">
                    <div class="tpsim-cm-title">${t(`cm_title`)}</div>
                    <div class="tpsim-cm-scorewrap">
                        <div class="tpsim-cm-score">${score}<span class="tpsim-cm-score-max">/100</span></div>
